    void analogPauseAndScreenshots(){MainWindow window;window.show();QVERIFY(window.loadExample("analog_rc"));window.startSimulation();auto* instruments=window.findChild<InstrumentPanel*>();std::string scope;for(const auto& p:window.circuit().parts())if(p.kind==PartKind::Oscilloscope)scope=p.id;QTRY_VERIFY(instruments->samples(scope).size()>300);auto* pause=window.findChild<QAction*>("pauseSimulation");pause->setChecked(true);auto last=instruments->samples(scope).back().time;QTest::qWait(80);QCOMPARE(instruments->samples(scope).back().time,last);window.findChild<QAction*>("stepSimulation")->trigger();QCOMPARE(instruments->samples(scope).back().time,last+100);window.resize(1400,1000);shot(window,"overall-analog-instruments");pause->setChecked(false);QTRY_VERIFY(instruments->samples(scope).back().time>last+100);window.stopSimulation();QTimer::singleShot(100,&window,[&]{auto* dialog=QApplication::activeModalWidget();QVERIFY(dialog);shot(*dialog,"hardware-build-upload");QMetaObject::invokeMethod(dialog,"reject");});window.findChild<QAction*>("hardwareTools")->trigger();}
