int main(int argc,char** argv){if(argc>1&&(QByteArray(argv[1])=="compile"||QByteArray(argv[1])=="upload")){QCoreApplication app(argc,argv);QStringList args=app.arguments();if(args[1]=="compile"){const auto path=args.back();if(!QFileInfo::exists(path+"/helper.h")||!QFileInfo::exists(path+"/helper.cpp")||!QFileInfo::exists(path+"/ThinkCadSketch.ino"))return 5;int index=args.indexOf("--build-path");if(index<0)return 6;QDir().mkpath(args[index+1]);QFile marker(args[index+1]+"/firmware.hex");if(!marker.open(QIODevice::WriteOnly))return 7;marker.write("test artifact");return 0;}return args.contains("COM42")?0:8;}QApplication app(argc,argv);WorkflowTests test;return QTest::qExec(&test,argc,argv);}
